\chapter{Wasser-Spiel: Leine, Haken und Köder}

Angeln ist die ergiebigste legale Fangtechnik für Anfänger: Fische verlernen keine Flucht wie Landwild, die Technik ist still, und der Aufwand pro Kalorie ist gering. Voraussetzung: du kennst die Haken-Montage, den Köder am Ort und die Wassertiefe, in der der Fisch steht.

\section{Grundausrüstung aus Bordmitteln}

\begin{tabular}{lp{4cm}p{5cm}}
\toprule
\tabkopf{Teil} & \tabkopf{Bordmittel} & \tabkopf{Maß / Prüfung} \\
\midrule
Angelrute & Gerade Hasel- oder Fichtenrute 2,5 bis 3,5 m & Biegeprobe mit 500 g an der Spitze, keine Risse \\
Schnur & Geflochtene Leine, Nähgarn verdreifacht, monofile Reste & Zugprobe mit 2 kg -- jede Schwachstelle bricht \\
Haken & Draht, Nadeln zu Häkchen gebogen, Drahtstifte & Spitze muss am Daumennagel hängen bleiben \\
Pose & Korkstück, Schwimmfeder, getrockneter Holunderstängel & Muss 3-mal so viel Auftrieb wie Blei-Gewicht haben \\
Blei & Muttern, kleine Steine in Netzstrümpfen & Nur so viel, dass die Pose noch trägt \\
\bottomrule
\end{tabular}
\captionof{table}{Angelgrundausrüstung aus Bordmitteln (Tab. 6.1)}
\vspace{6pt}

\section{Konzepte}

\begin{konzept}{6.1}{Montage: Pose, Blei, Vorfach}
\textbf{Definition:} Die Montage ist die Reihenfolge Pose--Blei--Vorfach--Haken an der Schnur, eingestellt auf die Tiefe, in der der Fisch steht.

\textbf{Dreifache Prüfung vor der Aufnahme:}
\begin{enumerate}
  \item Tiefenmessung: Senke die Schnur ohne Köder bis zum Grund; notiere die Tiefe, stelle die Pose auf Grundtiefe minus 10 bis 30 cm.
  \item Tragefähigkeit: Die Pose muss sichtbar kippen, wenn der Haken belastet wird -- prüfe mit nassem Brot statt Fisch.
  \item Knotenfestigkeit: Jeder Knoten hält das 1,5-fache des erwarteten Fischgewichts (Faustwert Zugprobe mit Stein).
\end{enumerate}

\textbf{Dreifache Bewertung nach bestandener Prüfung:}
\begin{enumerate}
  \item Köderpräsentation: Treibt der Köder in der richtigen Tiefe, ohne Grundberührung?
  \item Bisserkennbarkeit: Zeigt die Pose jeden Testbiss (Ziehen am Vorfach von Hand) an?
  \item Landungsquote: Übersteht die Montage den Drill eines Fisches über 500 g?
\end{enumerate}

\textbf{Ehrliche Grenzen:} Selbstgebogene Haken reißen bei Fischen über 1,5 kg aus -- Grenze der Bordmitteltechnik; örtlich prüfen, ob echte Haken vorhanden sind. Fließwasser braucht mehr Blei; stehendes Wasser weniger.
\end{konzept}

\begin{konzept}{6.2}{Köder: was der Fisch am Ort nimmt}
\textbf{Definition:} Der Köder ist das Lockmittel am Haken, gewählt nach Wasser, Jahreszeit und Zielfisch -- immer das, was der Fisch ohnehin frisst.

\textbf{Dreifache Prüfung vor der Aufnahme:}
\begin{enumerate}
  \item Naturköder sammeln: Regenwürmer (unter feuchten Brettern und Steinen), Insektenlarven (unter Steinen im Wasser), Brot und Teig aus Vorrat.
  \item Wasserprobeköder: Was schwimmt im Uferbereich --matching to -- choose das als Köder (Köcherfliegenlarven, Schnecken), denn das kennt der Fisch.
  \item Frischetest: Regenwürmer bleiben 2 bis 3 Tage in feuchtem Moos; tote Köder fangen kaum.
\end{enumerate}

\textbf{Dreifache Bewertung nach bestandener Prüfung:}
\begin{enumerate}
  \item Bissquote: Wie viele Bisse pro Stunde zeigt die Pose (Maßstab: 2 Bisse pro Stunde bei Karpfen und Brassen)?
  \item Zielfischtreue: Nimmt der Zielfisch den Köder, oder kommen nur Kleinfische?
  \item Verfügbarkeit: Lässt sich der Köder in 30 Minuten nachschaffen, wenn er ausgeht?
\end{enumerate}

\textbf{Ehrliche Grenzen:} Köderwirksamkeit ist örtlich und jahreszeitlich verschieden -- es gibt keine allgemein gültige Bissgarantie. Faustwert: Bei null Bissen über zwei Stunden Köder wechseln, nicht Wasser.
\end{konzept}

\begin{konzept}{6.3}{Fischspeer und Harpune}
\textbf{Definition:} Der Fischspeer ist eine Dreizack-Spitze mit Widerhaken an einer Rute, eingesetzt im flachen, klaren Wasser auf unter 2 m Distanz.

\textbf{Dreifache Prüfung vor der Aufnahme:}
\begin{enumerate}
  \item Brechungswinkel: Licht bricht an der Wasseroberfläche -- der Fisch steht tiefer, als er scheint; übe das Abschätzen mit einem Stein am Grund.
  \item Spitzenprüfung: Drei Spitzen im 60-Grad-Winkel, Widerhaken 3 mm, gehärtet; jede bewegliche Spitze vorher zum Stechen auf Holz.
  \item Standortwahl: Nur klares, stehendes oder langsam fließendes Wasser mit Uferdeckung.
\end{enumerate}

\textbf{Dreifache Bewertung nach bestandener Prüfung:}
\begin{enumerate}
  \item Trefferquote: Triffst du unter 2 m Distanz einen Zehnzentimeter-Zielball in 50 cm Tiefe in 5 von 10 Würfen?
  \item Landungsquote: Bleibt der Fisch nach dem Treffer am Speer (Widerhaken wirksam)?
  \item Fluchtquote: Wie viele Fische fliehen nach dem ersten Wurf -- ein Rastplatz braucht danach mehrere Stunden Ruhe.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Fischspeere sind in trübem Wasser nutzlos; in Strömung nur mit Stehgurt; in der Stadt sind Teichanlagen und Kanäle die einzigen Gewässer. Grenzfall Ausnahme: Nachts mit Lampe, wenn Fische ruhig stehen -- örtlich prüfen.
\end{konzept}

\section{Angeln -- Schrittfolge}

\begin{enumerate}
  \item Wähle den Platz: Kanten, Einläufe, Schatten unter Bäumen, Seerosenfelder -- Fische stehen an Strukturen, nicht in der Leere.
  \item Messe die Tiefe, stelle die Pose auf Grundtiefe minus 10 bis 30 cm.
  \item Ködere den Haken: Wurm ganz aufziehen, Spitze frei lassen, kein Köderschwanz länger als 3 cm.
  \item Wirf 3 bis 5 m von der Kante aus, niemals über die Fische hin.
  \item Beobachte die Pose 2 Stunden; bei jedem Zucken: 3 Sekunden warten, dann ruhig anheben -- kein Ruck.
  \item Lande den Fisch mit Ködernetz (Konzept 7.2) oder feuchtem Tuch; greife niemals mit trockener Hand ins Maul.
  \item Töte den Fisch sofort (Schlag auf den Kopf mit Knüppel, danach Kiemenschnitt) und hänge ihn an einer Schnur ins Schattenwasser.
\end{enumerate}

